    # We need to check if these two segments intersect

    # Function to check if two line segments intersect
    def segments_intersect(x1, y1, x2, y2, x3, y3, x4, y4):
        # Helper function to check if two points are collinear
        def collinear(x1, y1, x2, y2, x3, y3):
            return (y3 - y1) * (x2 - x1) == (y2 - y1) * (x3 - x1)

        # Helper function to check if a point is on a line segment
        def on_segment(x1, y1, x2, y2, x3, y3):
            return min(x1, x2) <= x3 <= max(x1, x2) and min(y1, y2) <= y3 <= max(y1, y2)

        # Check if the segments intersect
        if collinear(x1, y1, x2, y2, x3, y3):
            return on_segment(x1, y1, x2, y2, x3, y3) or on_segment(x3, y3, x4, y4, x1, y1)

